    public AccountService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new AccountEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(AccountRepository.class) );
		this.validator		= applicationContext.getBean(AccountValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Account
	 */
		public Account createAccount( CreateAccountCommand command ) {

		Account entity = new Account();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setAccountId( command.getAccountId() );
            entity.setName( command.getName() );
            entity.setAccountNumber( command.getAccountNumber() );
            entity.setIndustry( command.getIndustry() );
            entity.setBillingAddress( command.getBillingAddress() );
            entity.setShippingAddress( command.getShippingAddress() );
            entity.setWebsite( command.getWebsite() );
            entity.setPhone( command.getPhone() );
            entity.setAsActive( command.getAsActive() );
            entity.setAccountType( command.getAccountType() );
            entity.setLifecycleStage( command.getLifecycleStage() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Account {0} ", entity.toString() );

		return entity;
	}

